const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const alive = JSON.parse(await fs.readFile(S+"\\_GIG_ALL_ALIVE.json","utf8"));

// 已知的同平台多域名（之前 #43/#44 验证过）
const SAME_PLATFORM = [
  { group:"Freelancer", members:["freelancer.com","freelancer.in"] },
];
// 检查是否有其他可疑的
const suspects = [];
const seenBase = {};
for (const a of alive) {
  const x = String(a.host).replace(/^www\./,"");
  const base = x.split(".")[0];
  (seenBase[base] ??= []).push(x);
}
for (const [b, hs] of Object.entries(seenBase)) if (hs.length>1) suspects.push({base:b, hosts:hs});

// Freelancer 家族：.com 和 .in 是同一后端
const real = alive.filter(a => String(a.host) !== "freelancer.in");
return {
  entries: alive.length,
  afterFreelancerDedupe: real.length,
  samePlatformGroups: SAME_PLATFORM,
  baseNameCollisions: suspects,
  note: "freelancer.in 与 freelancer.com 是同一平台的不同地区站，应算 1 个"
};
